module TopModule (
    input  logic clk,
    input  logic reset,
    input  logic data,
    input  logic done_counting,
    input  logic ack,
    output logic shift_ena,
    output logic counting,
    output logic done
);

    typedef enum logic [1:0] {
        S_SEARCH = 2'b00,
        S_SHIFT  = 2'b01,
        S_COUNT  = 2'b10,
        S_DONE   = 2'b11
    } state_t;

    state_t state, next_state;
    logic [3:0] sr;
    logic [1:0] cnt;

    // State transition (synchronous active-high reset)
    always_ff @(posedge clk) begin
        if (reset) begin
            state <= S_SEARCH;
        end else begin
            state <= next_state;
        end
    end

    // Shift register for pattern detection (1101)
    always_ff @(posedge clk) begin
        if (reset) begin
            sr <= 4'b0000;
        end else if (state == S_SEARCH) begin
            sr <= {sr[2:0], data};
        end
    end

    // Cycle counter for S_SHIFT state (counts 4 cycles)
    always_ff @(posedge clk) begin
        if (reset) begin
            cnt <= 2'd0;
        end else if (state == S_SHIFT) begin
            cnt <= cnt + 2'd1;
        end else begin
            cnt <= 2'd0;
        end
    end

    // Next state logic
    always_comb begin
        next_state = state;
        case (state)
            S_SEARCH: begin
                if ({sr[2:0], data} == 4'b1101) begin
                    next_state = S_SHIFT;
                end
            end
            S_SHIFT: begin
                if (cnt == 2'd3) begin
                    next_state = S_COUNT;
                end
            end
            S_COUNT: begin
                if (done_counting) begin
                    next_state = S_DONE;
                end
            end
            S_DONE: begin
                if (ack) begin
                    next_state = S_SEARCH;
                end
            end
            default: begin
                next_state = S_SEARCH;
            end
        endcase
    end

    // Output assignments
    assign shift_ena = (state == S_SHIFT);
    assign counting  = (state == S_COUNT);
    assign done      = (state == S_DONE);

endmodule

